            // IntentFilter.matchCategories: every intent category must be
            // declared by the receiver's filter).
            std::vector<std::string> c7_intent_cats;
            // ── CODER7 WAVE-3: the intent's own matchData dimensions (AOSP
            // IntentFilter.matchData(intent.getType(), scheme, data)).
            std::string c7_intent_type, c7_intent_scheme, c7_intent_host,
                c7_intent_path;
