                // sender-identity aware): the sender must hold
                // android:permission (ReceiverInfo.permission) — the
                // running package reads its uses-permissions; a foreign
                // (modeled) sender reads MINIANDROID_C7_SENDER_PERMS.
                if (!mr.permission.empty() &&
                    !c7_sender_holds(mr.permission)) {
                    miniandroid::diagnostics::FileIoTrace::instance().record(
                        "BCAST-DENY", mr.cls, false,
                        "receiver permission " + mr.permission +
                            " not held by sender",
                        current_class_ + "." + current_method_);
                    continue;
                }
